<p>Request one source address and one destination for studio review. This workflow does not change email delivery or activate forwarding. Wildcards, multiple destinations, replacements and deletions are not available here.</p>
<?php if($forwardingUnavailable):?><p class="notice">The studio needs to review the forwarding request records. Please contact the studio.</p><?php else: ?>
<section data-forwarding-create><h2>Request review</h2><?php if(!$forwardingOptions):?><p>No new requests are available. Ask the studio to enable separate forwarding permission and refresh your domain assignment.</p><?php endif;?><div class="workspace-grid">
<?php foreach($forwardingOptions as $option):$b=$option['resource']['binding'];$retry=is_string($_POST['link_id']??null)&&$_POST['link_id']===$b['link_id'];$field=static fn(string $key,string $fallback,int $max=64):string=>$retry&&is_string($_POST[$key]??null)?substr($_POST[$key],0,$max):$fallback;?>
<article class="workspace-card"><h3 style="overflow-wrap:anywhere"><?=esc($b['domain'])?></h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="forwarding_create"><input type="hidden" name="request_id" value="<?=esc($field('request_id',bin2hex(random_bytes(16))))?>"><input type="hidden" name="link_id" value="<?=esc($b['link_id'])?>"><input type="hidden" name="permission_id" value="<?=esc($field('permission_id',$option['permission']['id']))?>"><input type="hidden" name="context" value="<?=esc($field('context',$option['context']))?>"><label>Source address before @<?=esc($b['domain'])?><input type="text" name="local" maxlength="64" value="<?=esc($field('local',''))?>" required></label><label>Destination email address<input type="email" name="remote" maxlength="254" value="<?=esc($field('remote','',254))?>" required></label><p class="hint">Use lowercase standard addresses. Existing forwarding and mailbox delivery have not been checked.</p><label><input type="checkbox" name="request_confirm" value="1" required> I am requesting studio review. This does not activate forwarding.</label><button class="btn gold">Request forwarding review</button></form></article><?php endforeach;?></div></section>
<section data-forwarding-history><h2>Your requests</h2><?php if(!$forwardingHistory):?><p>No requests on this page.</p><?php endif;?><?php foreach($forwardingHistory as $doc)provider_forwarding_render_history($doc,false);$page=max(1,min(10000,(int)($_GET['forwarding_page']??1)));?><nav class="button-row" aria-label="Forwarding request pages"><?php if($page>1):?><a class="btn outline" href="<?=esc(studio_url(['forwarding'=>1,'forwarding_page'=>$page-1]))?>">Newer requests</a><?php endif;?><?php if(count($forwardingHistory)===20&&$page<10000):?><a class="btn outline" href="<?=esc(studio_url(['forwarding'=>1,'forwarding_page'=>$page+1]))?>">Older requests</a><?php endif;?></nav></section><?php endif;?><a class="btn outline" href="<?=esc(studio_url(['forwarding'=>1]))?>">Refresh request forms</a>
